"""Exact-source native close-state correction applied after channel UDP patch."""
from pathlib import Path

OLD = "static void ov_close(Cpu *c) {\n    int fd = (int)arg_x(c, 0);\n    plat_mutex_lock(&fd_lock);\n    GFd *f = fd_get(fd, 0);\n    HostSock s = f ? f->s : HOST_BAD, w = f ? f->w : HOST_BAD;\n    if (f) f->kind = FD_FREE;\n    plat_mutex_unlock(&fd_lock);\n    if (!f) return ret_fail(c, G_EBADF);\n    if (udp_trace() && f->kind == FD_FREE && f->type == 2) {\n        uint64_t now = plat_now_ns();\n        uint64_t tx = __atomic_load_n(&f->udp_tx_packets, __ATOMIC_RELAXED);\n        uint64_t rx = __atomic_load_n(&f->udp_rx_packets, __ATOMIC_RELAXED);\n        uint64_t last_rx = __atomic_load_n(&f->udp_rx_last_ns, __ATOMIC_RELAXED);\n        uint64_t last_tx = __atomic_load_n(&f->udp_tx_last_ns, __ATOMIC_RELAXED);\n        rt_log(\"net-udp: fd=%d closed tx=%llu rx=%llu rx_idle_ms=%llu tx_idle_ms=%llu gaps_rx=%u gaps_tx=%u errors=%u\",\n               fd, (unsigned long long)tx, (unsigned long long)rx,\n               (unsigned long long)(last_rx && now >= last_rx ? (now - last_rx) / 1000000ull : 0),\n               (unsigned long long)(last_tx && now >= last_tx ? (now - last_tx) / 1000000ull : 0),\n               f->udp_rx_gaps, f->udp_tx_gaps, f->udp_errors);\n    }\n    if (s != HOST_BAD) host_close(s);\n    if (w != HOST_BAD) host_close(w);\n    ret_x(c, 0);\n}"
NEW = "static void ov_close(Cpu *c) {\n    int fd = (int)arg_x(c, 0);\n    uint64_t tx = 0, rx = 0, last_rx = 0, last_tx = 0;\n    uint32_t gaps_rx = 0, gaps_tx = 0, errors = 0;\n    int was_udp = 0;\n    plat_mutex_lock(&fd_lock);\n    GFd *f = fd_get(fd, 0);\n    HostSock s = f ? f->s : HOST_BAD, w = f ? f->w : HOST_BAD;\n    // Snapshot diagnostics before making the descriptor reusable by another\n    // game thread; otherwise a fresh socket's counters can be read on close.\n    if (f) {\n        was_udp = f->type == 2 && udp_trace();\n        if (was_udp) {\n            tx = __atomic_load_n(&f->udp_tx_packets, __ATOMIC_RELAXED);\n            rx = __atomic_load_n(&f->udp_rx_packets, __ATOMIC_RELAXED);\n            last_rx = __atomic_load_n(&f->udp_rx_last_ns, __ATOMIC_RELAXED);\n            last_tx = __atomic_load_n(&f->udp_tx_last_ns, __ATOMIC_RELAXED);\n            gaps_rx = __atomic_load_n(&f->udp_rx_gaps, __ATOMIC_RELAXED);\n            gaps_tx = __atomic_load_n(&f->udp_tx_gaps, __ATOMIC_RELAXED);\n            errors = __atomic_load_n(&f->udp_errors, __ATOMIC_RELAXED);\n        }\n        f->kind = FD_FREE;\n    }\n    plat_mutex_unlock(&fd_lock);\n    if (!f) return ret_fail(c, G_EBADF);\n    if (was_udp) {\n        uint64_t now = plat_now_ns();\n        rt_log(\"net-udp: fd=%d closed tx=%llu rx=%llu rx_idle_ms=%llu tx_idle_ms=%llu gaps_rx=%u gaps_tx=%u errors=%u\",\n               fd, (unsigned long long)tx, (unsigned long long)rx,\n               (unsigned long long)(last_rx && now >= last_rx ? (now - last_rx) / 1000000ull : 0),\n               (unsigned long long)(last_tx && now >= last_tx ? (now - last_tx) / 1000000ull : 0),\n               gaps_rx, gaps_tx, errors);\n    }\n    if (s != HOST_BAD) host_close(s);\n    if (w != HOST_BAD) host_close(w);\n    ret_x(c, 0);\n}"


def apply(path: Path) -> None:
    source = path.read_text(encoding="utf-8")
    if source.count(OLD) != 1:
        raise ValueError("MKWOM native socket close source drift: expected exact original function once")
    path.write_text(source.replace(OLD, NEW, 1), encoding="utf-8")
